    {reportTab==='funds'&&<div className="table-wrap"><table className="data-table"><thead><tr><th>Transaction</th><th>Date</th><th>Branch</th><th>Fund / Type</th><th className="num">Amount</th><th>Status</th></tr></thead><tbody>{filterBranch(db.fundEntries).filter(e=>user.role==='pb'?e.fund==='RFP':user.role==='cashier'?e.fund==='RF':true).filter(e=>inDate(e.date)).slice((reportPage-1)*30,reportPage*30).map(e=><tr key={e.id}><td className="mono td-id">{e.no}</td><td>{datePH(e.date)}</td><td>{e.branch}</td><td>{e.fund} · {e.kind}</td><td className="num">{pesos(e.amount)}</td><td><StatusPill status={e.status}/></td></tr>)}</tbody></table><div className="pagination"><button className="button button-secondary" disabled={reportPage===1} onClick={()=>setReportPage(n=>n-1)}>Previous</button><span>Page {reportPage} · 30 per page</span><button className="button button-secondary" disabled={filterBranch(db.fundEntries).filter(e=>user.role==='pb'?e.fund==='RFP':user.role==='cashier'?e.fund==='RF':true).filter(e=>inDate(e.date)).length<=reportPage*30} onClick={()=>setReportPage(n=>n+1)}>Next</button></div>{user.role!=='pb'&&<div className="report-category-summary"><strong>Revolving Fund · Category Totals</strong><div className="category-grid">{Object.entries(categoryTotals(filterBranch(db.fundEntries).filter(e=>inDate(e.date)))).sort((a,b)=>b[1]-a[1]).map(([category,amount])=><div className="category-item" key={category}><span>{category}</span><strong>{pesos(amount)}</strong></div>)}</div></div>}</div>}
